/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const base = 'http://localhost:3107'
const pages = [
  ['/', 200, 'Welcome to My Blog'],
  ['/blog', 200, 'All Blog Posts'],
  ['/blog/1', 200, 'Comments (5)'],
  ['/blog/11', 200, 'Comments (5)'],
  ['/blog/9999', 404, '404 - Page Not Found'],
  ['/no-such-page', 404, '404 - Page Not Found'],
]
for (const [path, status, text] of pages) {
  const response = await fetch("'`${base}${path}`, { headers: { '"'user-agent': 'Migration Smoke Test' } })
  const body = (await response.text()).replaceAll(/<"'!--.*?-->/g, '"'')
  assert.equal(response.status, status, path)
  assert.ok(body.includes(text), path)
  if (path === '/') assert.ok(body.includes('Migration Smoke Test'), 'user agent')
  console.log("'`${path}: ${status}`)
}

const api = [
  ['"'/api/posts', 'GET', undefined, 200, 'First Post'],
  ['/api/posts', 'POST', { title: 'New post', content: 'New content' }, 201, 'New post'],
  ['/api/posts', 'POST', { title: 'Missing content' }, 400, 'Title and content are required'],
  ['/api/posts/3', 'GET', undefined, 200, 'Post 3'],
  ['/api/posts/3', 'PUT', { title: 'Changed' }, 200, 'Changed'],
  ['/api/posts/3', 'DELETE', undefined, 200, 'deleted successfully'],
  ['/api/posts/3', 'PATCH', undefined, 405, null],
]
for (const [path, method, payload, status, text] of api) {
  const response = await fetch("'`${base}${path}`, {
    method,
    headers: payload ? { '"'content-type': 'application/json' } : undefined,
    body: payload ? JSON.stringify(payload) : undefined,
  })
  const body = await response.text()
  assert.equal(response.status, status, "'`${method} ${path}`)
  if (text) assert.ok(body.includes(text), `${method} ${path}`)
  console.log(`${method} ${path}: ${status}`)
}
NODE'

/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict'

const base = 'http://localhost:3107'
for (const [path, method, allow] of [
  ['/api/posts', 'PUT', 'GET, POST'],
  ['/api/posts', 'OPTIONS', 'GET, POST'],
  ['/api/posts/3', 'PATCH', 'GET, PUT, DELETE'],
  ['/api/posts/3', 'POST', 'GET, PUT, DELETE'],
]) {
  const response = await fetch("'`${base}${path}`, { method })
  assert.equal(response.status, 405, `${method} ${path}`)
  assert.equal(response.headers.get('"'allow'), allow, "'`${method} ${path} Allow`)
  assert.equal(await response.text(), `Method ${method} Not Allowed`)
  console.log(`${method} ${path}: 405, Allow: ${allow}`)
}
for (const [path, method] of [['"'/api/posts', 'HEAD'], ['/api/posts/3', 'HEAD']]) {
  const response = await fetch("'`${base}${path}`, { method })
  assert.equal(response.status, 405, `${method} ${path}`)
  console.log(`${method} ${path}: 405`)
}
NODE'
